# Code Generated by Sidekick is for learning and experimentation purposes only.
# filename: RECON-05-GetResults.ps1

$BASE = "http://localhost:8009/reconcile/results"

# ── All results ───────────────────────────────────────────────────────────────
Write-Host "`n► GET $BASE  (all)" -ForegroundColor Yellow
try {
    $all = Invoke-RestMethod -Uri $BASE -Method GET
    Write-Host "✓ $($all.Count) run(s) found" -ForegroundColor Green
    foreach ($run in $all) {
        $col = if ($run.discrepancies_found -eq 0) { "Green" } else { "Red" }
        Write-Host "  $($run.run_id) | $($run.trigger) | $($run.status) | Payments=$($run.total_payments) | Discrepancies=$($run.discrepancies_found)" -ForegroundColor $col
    }
} catch { Write-Host "✗ Failed: $_" -ForegroundColor Red }

# ── Only scheduled runs ───────────────────────────────────────────────────────
Write-Host "`n► GET $BASE`?trigger=SCHEDULED" -ForegroundColor Yellow
try {
    $sched = Invoke-RestMethod -Uri "$BASE`?trigger=SCHEDULED" -Method GET
    Write-Host "  Scheduled runs: $($sched.Count)" -ForegroundColor Cyan
    $sched | ConvertTo-Json -Depth 2
} catch { Write-Host "✗ Failed: $_" -ForegroundColor Red }

# ── Only manual runs ──────────────────────────────────────────────────────────
Write-Host "`n► GET $BASE`?trigger=MANUAL" -ForegroundColor Yellow
try {
    $manual = Invoke-RestMethod -Uri "$BASE`?trigger=MANUAL" -Method GET
    Write-Host "  Manual runs: $($manual.Count)" -ForegroundColor Cyan
} catch { Write-Host "✗ Failed: $_" -ForegroundColor Red }
